jinja.template:
{#- Inkling 2 chat template adapted for hanashi (minijinja):
    - tojson has no sort_keys/separators here, so compact_json writes the same compact JSON;
    - the HF-only generation/endgeneration tags are dropped;
    - tool calls are {name, arguments} objects, tool results arrive as {name, response} (wrapped as {"value": ...} if not an object);
    - add_generation_prompt opens the reply with <|message_model|>, the token the model starts every reply with. -#}
{%- set effort_map = {"none": 0.0, "minimal": 0.1, "low": 0.2, "medium": 0.7, "high": 0.9, "xhigh": 0.99, "max": 0.99} -%}
{%- set role_token = {"user": "<|message_user|>", "assistant": "<|message_model|>", "system": "<|message_system|>", "tool": "<|message_tool|>"} -%}

{%- macro compact_json(value, sort_keys) -%}
    {%- if value is mapping -%}
        {{- "{" -}}
        {%- for key, item in (value | dictsort(case_sensitive=true) if sort_keys else value | items) -%}
            {{- "," if not loop.first -}}
            {{- key | tojson -}}
            {{- ":" -}}
            {{- compact_json(item, sort_keys) -}}
        {%- endfor -%}
        {{- "}" -}}
    {#- Lists built with `+` are lazy iterables in minijinja, not sequences; none and undefined iterate as empty. -#}
    {%- elif value is defined and value is not none and value is not string and value is iterable -%}
        {{- "[" -}}
        {%- for item in value -%}
            {{- "," if not loop.first -}}
            {{- compact_json(item, sort_keys) -}}
        {%- endfor -%}
        {{- "]" -}}
    {%- else -%}
        {{- value | tojson -}}
    {%- endif -%}
{%- endmacro -%}

{%- macro emit_thinking_effort() -%}
    {%- set eff = reasoning_effort if reasoning_effort is defined and reasoning_effort is not none else 0.9 -%}
    {%- if eff is string -%}
        {%- set key = eff | trim -%}
        {%- if key not in effort_map -%}
            {{- raise_exception("Unknown reasoning_effort: " ~ eff) -}}
        {%- endif -%}
        {%- set num = effort_map[key] -%}
    {%- else -%}
        {%- set num = eff | float -%}
    {%- endif -%}
    {%- if num < 0.0 or num > 0.99 -%}
        {{- raise_exception("reasoning_effort must be in [0.0, 0.99]") -}}
    {%- endif -%}
    {{- "<|message_system|><|content_text|>Thinking effort level: " -}}
    {%- if num == 0.0 -%}0{%- else -%}{{ num }}{%- endif -%}
    {{- "<|end_message|>" -}}
{%- endmacro -%}

{%- if tools -%}
    {%- set tool_state = namespace(specs=[]) -%}
    {%- for tool in tools -%}
        {%- set fn = tool.function if tool.function is defined else tool -%}
        {%- set spec = {
            "description": (fn.description if fn.description is defined and fn.description else ""),
            "name": fn.name,
            "parameters": (fn.parameters if fn.parameters is defined and fn.parameters else {}),
            "type": (tool.type if tool.type is defined and tool.type else "function"),
        } -%}
        {%- set tool_state.specs = tool_state.specs + [spec] -%}
    {%- endfor -%}
    {{- "<|message_system|>tool_declare<|content_xml|>" -}}
    {{- compact_json(tool_state.specs, true) -}}
    {{- "<|end_message|>" -}}
{%- endif -%}

{%- set state = namespace(effort_emitted=false) -%}
{%- for message in messages -%}
    {%- if message.role not in role_token -%}
        {{- raise_exception("Unknown message role: " ~ message.role) -}}
    {%- endif -%}
    {%- if not state.effort_emitted and message.role != "system" -%}
        {{- emit_thinking_effort() -}}
        {%- set state.effort_emitted = true -%}
    {%- endif -%}

    {%- set message_state = namespace(content=message.content, name=(message.name if message.name is defined else none)) -%}
    {%- if message.role == "tool" -%}
        {%- if message.content is mapping and message.content | length == 2 and "name" in message.content and "response" in message.content -%}
            {%- set message_state.name = message.content.name -%}
            {%- set message_state.content = message.content.response -%}
            {%- if message_state.content is mapping and message_state.content | length == 1 and "value" in message_state.content -%}
                {%- set message_state.content = message_state.content.value -%}
            {%- endif -%}
        {%- endif -%}
        {%- if message_state.content is not string -%}
            {%- set message_state.content = compact_json(message_state.content, false) -%}
        {%- endif -%}
    {%- endif -%}

    {%- set header = namespace(text=role_token[message.role]) -%}
    {%- if message.role == "tool" -%}
        {%- if message_state.name is string and message_state.name -%}
            {%- set header.text = header.text ~ message_state.name -%}
        {%- endif -%}
    {%- elif message.role == "assistant" and message.name is defined and message.name -%}
        {%- set header.text = header.text ~ message.name -%}
    {%- endif -%}
    {%- set rtok = header.text -%}
    {%- set rendered -%}

    {%- if message.role == "assistant" and message.reasoning_content is defined and message.reasoning_content -%}
        {{- rtok ~ "<|content_thinking|>" ~ message.reasoning_content ~ "<|end_message|>" -}}
    {%- endif -%}

    {%- if message_state.content is string and (message_state.content or not (message.role == "assistant" and (message.tool_calls or message.reasoning_content))) -%}
        {{- rtok ~ "<|content_text|>" ~ message_state.content ~ "<|end_message|>" -}}
    {%- elif message_state.content -%}
        {%- for part in message_state.content -%}
            {%- if part is string -%}
                {{- rtok ~ "<|content_text|>" ~ part ~ "<|end_message|>" -}}
            {%- elif part.type is not defined or part.type in ("text", "input_text") -%}
                {%- set text_part = (part.text if part.text is defined and part.text is string else "") -%}
                {{- rtok ~ "<|content_text|>" ~ text_part ~ "<|end_message|>" -}}
            {%- elif part.type in ("image", "input_image", "image_url") -%}
                {%- if message.role not in ("user", "tool") -%}
                    {{- raise_exception("Image content is only supported for user and tool messages") -}}
                {%- endif -%}
                {{- rtok ~ "<|content_image|><|unused_200054|><|end_message|>" -}}
            {%- elif part.type in ("audio", "input_audio", "audio_url") -%}
                {{- raise_exception("Inkling 2 does not accept audio input") -}}
            {%- else -%}
                {{- raise_exception("Unsupported content part type: " ~ part.type) -}}
            {%- endif -%}
        {%- endfor -%}
    {%- endif -%}

    {%- if message.role == "assistant" and message.tool_calls -%}
        {%- for tc in message.tool_calls -%}
            {%- set fn = tc.function if tc is mapping and tc.function is defined else tc -%}
            {#- Unparsed tool call candidates have no name: they are skipped instead of failing the prompt. -#}
            {%- if fn is mapping and fn.name is string -%}
                {%- if message.name is defined and message.name and message.name != fn.name -%}
                    {{- raise_exception("assistant name " ~ message.name ~ " does not match its tool call " ~ fn.name) -}}
                {%- endif -%}
                {%- set args = fn.arguments if fn.arguments is defined and fn.arguments else {} -%}
                {{- "<|message_model|>" ~ fn.name ~ "<|content_invoke_tool_json|>" -}}
                {{- '{"name":' ~ (fn.name | tojson) ~ ',"args":' -}}
                {%- if args is mapping -%}
                    {{- "{" -}}
                    {%- for key, value in args | dictsort(case_sensitive=true) -%}
                        {{- (key | tojson) ~ ":" ~ compact_json(value, false) -}}
                        {%- if not loop.last -%},{%- endif -%}
                    {%- endfor -%}
                    {{- "}" -}}
                {%- else -%}
                    {#- Arguments that are not an object are kept as generated instead of failing the prompt. -#}
                    {{- compact_json(args, false) -}}
                {%- endif -%}
                {{- "}<|end_message|>" -}}
            {%- endif -%}
        {%- endfor -%}
    {%- endif -%}

    {%- if message.role == "assistant" -%}
        {{- "<|content_model_end_sampling|>" -}}
    {%- endif -%}
    {%- endset -%}
    {{- rendered -}}
{%- endfor -%}

{%- if not state.effort_emitted -%}
    {{- emit_thinking_effort() -}}
{%- endif -%}

{%- if add_generation_prompt -%}
    {{- "<|message_model|>" -}}
{%- endif -%}
